sp_widget.client_script:
function() {
  	var c = this;

	var rejectNote = "";
	c.resolveCase = function() {
		if (c.data.resolutionAction == "accept") 
			acceptResolution();
		else if (c.data.resolutionAction == "reject") {
			rejectNote = c.data.rejectResolutionNote.trim();
			rejectResolution();
		}
		$('#acceptRejectModal').modal('hide');
	}

	acceptResolution = function() {
		c.server.get({
			action: 'sendResponse',
			purpose: 'accept',
			state: 7,
			acceptResolutionNote: 'Resolution accepted, request closed.'
		});
	};

	rejectResolution = function() {
		c.server.get({
			action: 'sendResponse',
			purpose: 'reject',
			state: 2,
			state_reason: 1,
			rejectResolutionNote : rejectNote
		});
	};

	var cancelNote = "";
	c.cancelUR = function() {
		cancelNote = c.data.cancelNotes.trim();
		c.server.get({
			action: 'cancel', 
			cancelNote: cancelNote
		});
		$('#cancelModal').modal('hide');
	}

}

sp_widget.css:
.dropdown {
  display: block;
  text-align: center;
}

.dropdown-item {
    padding: 10px 15px;
    display: block;
    color: #293E40;
}

.show {
    display: block !important;
}

.backdrop {
    position: fixed;
    left: 0;
    right: 0;
    top: 0;
    bottom: 0;
    background: black;
    opacity: 0.5;
}

.icon-cross:before {
	content: "\f153";
	font-size: 6px;
	height: 13px;
	width: 13px;
	background: #000000;
	border-radius: 50%;
	color: white;
	line-height: 2;
}

.fa-close {
  margin-top: 20px;
  cursor: pointer;
}

.actions-pad {
  padding-right: 2px !important;
}

.modal-body textarea {
	resize: none !important;
	box-sizing: border-box;
	border-radius: 4px;
	border: 1px solid #CCCCCC;
}

.modalPosition {
  top : 30%;
  right : 3%;
  outline : none;
}

.modalTitle {
  font-size: 17px !important;
  font-weight: 600;
  letter-spacing: 0;
  padding-top: 10px;
  text-align: left;
  color: black;
}

.modalHeader {
  border-bottom: 0px;
  padding-top: 8px;
  padding-bottom: 8px;
} 

.modalBody {
  padding-top: 20px;
  padding-bottom: 20px;
  padding-right: 20px;
}

.crossButton {
  font-size: 12px;
}

.controls-radio input {
  position: absolute;
  opacity: 0;
  cursor: pointer;
}

/* Hide the browser's default radio button */
.container input {
  position: absolute;
  opacity: 0;
  cursor: pointer;
}

/* Create a custom radio button */
.checkmark {
  position: absolute;
  top: 0;
  left: 0;
  height: 20px;
  width: 20px;
  background-color: #fff;
  border-radius: 100px;
  border: 1px solid #BDC0C4
}

/* When the radio button is checked, add a blue background */
.controls-radio input:checked ~ .checkmark {
  background-color: #fff;
  border: 1px solid #BDC0C4
}

.textMargin {
  margin-left: 5px;
  margin-bottom: 15px;
  text-align: left;
}

/* Create the indicator (the dot/circle - hidden when not checked) */
.checkmark:after {
  content: "";
  position: absolute;
  display: none;
}

/* Show the indicator (dot/circle) when checked */
.controls-radio input:checked ~ .checkmark:after {
  display: block;
}

/* Style the indicator (dot/circle) */
.controls-radio .checkmark:after {
 	top: 4px;
	left: 4px;
	width: 10px;
	height: 10px;
	border-radius: 100px;
	background: #1C796B;
}

sp_widget.script:
(function() {
  	var tableName = $sp.getParameter('table');
	var sysId = $sp.getParameter('sys_id');

	var record = sn_std_tkt_api.TicketConfig.getTicketRecord(tableName, sysId);
	data.canRead = (record !== null && record.isValid() && record.canRead());
	if (!data.canRead)
		return;

	data.valid = false;
	data.showCancel = false;
	var hasPrimaryTask = record.primary_task;
	var state = record.state;
	var stateReason = record.state_reason;
	if (tableName === 'universal_request' && !hasPrimaryTask && record.active) {
		if (state == UniversalRequestStateSNC.AWAITING_RESPONSE_FROM_USER && stateReason == UniversalRequestStateSNC.STATE_REASON.AWAITING_RESPONSE_FROM_USER.ACCEPT_RESOLUTION)
			data.valid = true;
		else {
			var universalRequestUtils = new UniversalRequestUtilsSNC();
			var taskGR = new GlideRecord(universalRequestUtils.TABLES.TASK);
			taskGR.query("universal_request",sysId);
			if(!taskGR.next())
				data.showCancel = true;
		}
	}

	if (input && input.action === 'sendResponse' ) {
		var universalGr = new GlideRecord(tableName);
		var acceptNotes;
		if (universalGr.get(sysId)) {
			universalGr.setValue('state', input.state);
			if (input.purpose === 'accept') {
				acceptNotes = input.acceptResolutionNote;
				universalGr.comments = acceptNotes;
			}

			else if (input.purpose === 'reject') {
				universalGr.setValue('state_reason', input.state_reason);
				var rejectNotes = gs.getMessage('[code]<b> Reason for rejection: </b>[/code] ') + input.rejectResolutionNote;
				universalGr.comments = rejectNotes;
			}
			var flag = universalGr.update();
			if (input.purpose === 'accept' && flag)
				gs.addInfoMessage(acceptNotes);
		}
		return;
	}

	if(input && input.action === 'cancel') {
		var universalGr = new GlideRecord(tableName);
		if(universalGr.get(sysId)) {
			universalGr.setValue('state', UniversalRequestStateSNC.CANCELED);
			var cancelNotes = input.cancelNote;
			if(cancelNotes) {
				universalGr.comments = cancelNotes;
				var canceled = universalGr.update();
				if (canceled)
					gs.addInfoMessage(gs.getMessage('{0} has been canceled',record.number));
			}
			else {
				gs.addErrorMessage(gs.getMessage("Please enter reason for closing request"));
				return;
			}
		}
	}

})();
